/// The title of a part of a tab in the right panel.
pub(super) fn section(ui: &mut egui::Ui, title: &str) {
    ui.add_space(8.0);
    ui.label(egui::RichText::new(title).strong());
    ui.separator();
}

/// The runs offered for a step (`only` or not): for the last step, both are the same.
fn run_choices(step: Step) -> &'static [bool] {
    if Step::ALL.last() == Some(&step) {
        &[true]
    } else {
        &[false, true]
    }
}

/// What a step's run menu item does, as planned: the range that will run, which starts earlier
/// when an earlier step is unfinished.
fn run_label(step: Step, run: Run) -> String {
    let from = if run.first == step {
        tl("ここ", "here").to_string()
    } else {
        format!("「{}」", short_step_label(run.first))
    };
    match run.last {
        Some(last) if last == run.first => tl("この工程だけ実行", "Run this step only").into(),
        Some(_) => tr!(
            "{from}からこの工程まで実行",
            "Run from {from} through this step"
        ),
        None => tr!("{from}から最後まで実行", "Run from {from} through the end"),
    }
}

/// Why a step's result is out of date, in a few words.
fn stale_text(why: Option<s20_pipeline::Stale>) -> &'static str {
    match why {
        Some(s20_pipeline::Stale::Earlier) => tl(
            "前の工程のやり直しが未反映",
            "An earlier step was redone and not applied",
        ),
        Some(s20_pipeline::Stale::Edits) => {
            tl("軌跡の修正が未反映", "Trajectory corrections not applied")
        }
        Some(s20_pipeline::Stale::Params) => {
            tl("設定の変更が未反映", "Settings changes not applied")
        }
        None => tl("未反映の変更あり", "Unapplied changes"),
    }
}

/// What the preview shows, as offered on the toolbar.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub(super) enum Preview {
    /// the scans placed with the device's own trajectory
    ScansDevice,
    /// the scans placed with the LIO trajectory
    ScansLio,
    /// the scans placed with the optimised trajectory
    ScansOpt,
    /// the output cloud before colouring (with the points colouring drops)
    OutputUncolored,
    /// the coloured output cloud
    Output,
}

impl Preview {
    const ALL: [Self; 5] = [
        Self::ScansDevice,
        Self::ScansLio,
        Self::ScansOpt,
        Self::OutputUncolored,
        Self::Output,
    ];

    fn label(self) -> &'static str {
        match self {
            Self::ScansDevice => tl("スキャン点群（機体）", "Scan point cloud (device)"),
            Self::ScansLio => tl("スキャン点群（LIO）", "Scan point cloud (LIO)"),
            Self::ScansOpt => tl("スキャン点群（最適化後）", "Scan point cloud (optimized)"),
            Self::OutputUncolored => tl("出力点群（着色前）", "Output point cloud (uncolored)"),
            Self::Output => tl("出力点群（着色済み）", "Output point cloud (colored)"),
        }
    }

    fn hint(self) -> &'static str {
        match self {
            Self::ScansDevice => tl(
                "生のスキャンを、機体が撮影中に推定して保存した軌跡（frame_pose.txt）で                 そのまま配置する（複数セッションは横に並べる）。軌跡の記録がない区間の点は出さない",
                "Places the raw scans as they are with the trajectory the device estimated and saved while recording (frame_pose.txt) (several sessions side by side). Points in sections without a recorded trajectory are left out",
            ),
            Self::ScansLio => tl(
                "生のスキャンを LIO の軌跡で配置する（複数セッションは横に並べる）",
                "Places the raw scans with the LIO trajectory (several sessions side by side)",
            ),
            Self::ScansOpt => tl(
                "生のスキャンを最適化した軌跡で配置する",
                "Places the raw scans with the optimized trajectory",
            ),
            Self::OutputUncolored => tl(
                "点群生成で出力した点群（output フォルダーの pointcloud_uncolorized）。\
                 着色で色が付かずに落ちる点も含む",
                "The point cloud written by the point cloud step (pointcloud_uncolorized in the output folder). Includes the points colorization drops for lack of a color",
            ),
            Self::Output => tl(
                "着色で出力した点群（output フォルダーの pointcloud_colorized）",
                "The point cloud written by colorization (pointcloud_colorized in the output folder)",
            ),
        }
    }
}

fn short_step_label(step: Step) -> &'static str {
    match step {
        Step::Extract => tl("データ取り込み", "Data import"),
        Step::Lio => tl("オドメトリ（LIO）", "Odometry (LIO)"),
        Step::Opt => tl("軌跡の最適化", "Trajectory optimization"),
        Step::Cloud => tl("点群生成", "Point cloud"),
        Step::Export => tl("軌跡・画像姿勢の出力", "Trajectory and image pose export"),
        Step::Refine => tl("画像の姿勢合わせ", "Image pose refinement"),
        Step::Colorize => tl("着色", "Colorization"),
        Step::Images => tl("画像の出力", "Image export"),
    }
}
